'use strict';
const $=s=>document.querySelector(s);
const userId=globalThis.__ONE_STEP_USER_ID;
if(!userId||!globalThis.__ONE_STEP_STORAGE_KEY||!globalThis.__ONE_STEP_DRAFT_KEY)throw Error('Authenticated user required');
const KEY=globalThis.__ONE_STEP_STORAGE_KEY, DRAFT=globalThis.__ONE_STEP_DRAFT_KEY;
const dateKey=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random().toString(36).slice(2)}`;
let state={tasks:[],settings:{timer:true,notify:false}},view='home',selected=null,picker=false,undo=null,toastTimeout,timer={task:null,end:0,left:300},storageOK=true;
try{const data=JSON.parse(localStorage.getItem(KEY));if(data&&Array.isArray(data.tasks))state={tasks:data.tasks,settings:{...state.settings,...data.settings}};$('#quick-input').value=localStorage.getItem(DRAFT)||''}catch{storageOK=false}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));$('#storage-note').textContent='이 브라우저에 자동 저장';storageOK=true}catch{storageOK=false;$('#storage-note').textContent='저장 공간을 확인해 주세요';toast('저장하지 못했어요. 설정에서 백업을 내려받아 주세요.')}}
function toast(message,action){clearTimeout(toastTimeout);$('#toast').hidden=false;$('#toast').innerHTML=esc(message)+(action?' <button id="undo">실행 취소</button>':'');if(action)$('#undo').onclick=()=>{action();$('#toast').hidden=true};toastTimeout=setTimeout(()=>$('#toast').hidden=true,action?12000:5000)}
function newTask(title){return{id:uid(),title,status:'todo',today:false,note:'',next:'',steps:[],start:'',due:'',priority:1,estimate:0,tag:'',repeat:'none',reminder:'',notified:'',condition:'',created:Date.now(),updated:Date.now(),completed:''}}
function active(){return state.tasks.find(t=>t.status==='active')}
function update(t){t.updated=Date.now();save()}
function start(t){const old=active();if(old&&old.id!==t.id){old.status='paused';old.updated=Date.now();toast('하던 일은 보류했어요. 메모와 진행 상태는 그대로예요.')}t.status='active';if(!t.today&&state.tasks.filter(x=>x.today&&x.status!=='done').length<3)t.today=true;update(t);timer={task:t.id,end:0,left:300};render()}
function complete(t){const before=JSON.stringify(state.tasks);if(t.status==='done'){t.status='todo';t.completed=''}else{t.status='done';t.completed=dateKey();if(t.repeat!=='none'){const next={...t,id:uid(),status:'todo',today:false,completed:'',notified:'',steps:t.steps.map(s=>({...s,id:uid(),done:false})),created:Date.now()};const d=new Date((t.due && t.due>dateKey()?t.due:dateKey())+'T12:00:00');d.setDate(d.getDate()+(t.repeat==='weekly'?7:1));next.due=dateKey(d);next.start=next.due;next.reminder='';state.tasks.push(next)}}update(t);render();toast(t.status==='done'?'한 걸음 마쳤어요. 수고했어요.':'다시 할 일에 담았어요.',()=>{state.tasks=JSON.parse(before);save();render()})}
function toggleToday(t){if(!t.today&&state.tasks.filter(x=>x.today&&x.status!=='done').length>=3){toast('오늘은 세 개까지만. 먼저 하나를 빼거나 마쳐보세요.');return}t.today=!t.today;update(t);render()}
function row(t){const meta=[t.status==='active'?'진행 중':t.status==='paused'?'잠시 보류':t.status==='waiting'?'답변 대기':'',t.next,t.due?`마감 ${t.due.slice(5).replace('-','. ')}`:'',t.priority===2?'우선순위 높음':'',t.tag].filter(Boolean).join(' · ');return`<div class="task-row"><button class="check ${t.status==='done'?'done':''}" data-action="done" data-id="${esc(t.id)}" aria-label="${esc(t.title)} ${t.status==='done'?'완료 취소':'완료'}">${t.status==='done'?'✓':''}</button><button class="task-info" data-action="edit" data-id="${esc(t.id)}"><span class="task-title ${t.status==='done'?'done-title':''}">${esc(t.title)}</span>${meta?`<span class="task-meta">${esc(meta)}</span>`:''}</button>${picker&&t.status!=='done'?`<button class="task-start" data-action="today" data-id="${esc(t.id)}">${t.today?'오늘에서 빼기':'오늘에 담기'}</button>`:t.status!=='done'&&t.status!=='active'?`<button class="task-start" data-action="start" data-id="${esc(t.id)}">시작 →</button>`:''}<button class="row-more" data-action="edit" data-id="${esc(t.id)}" aria-label="${esc(t.title)} 상세 옵션">⋯</button></div>`}
function render(){const today=dateKey();$('#date-label').textContent=new Intl.DateTimeFormat('ko-KR',{month:'long',day:'numeric',weekday:'long'}).format(new Date());$('#all-count').textContent=state.tasks.filter(t=>t.status!=='done').length;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#home-view').hidden=view!=='home';$('#list-view').hidden=view==='home';const titles={home:['오늘은 하나씩 해볼까요?','생각은 가볍게 내려놓고, 눈앞의 한 가지부터.'],all:[picker?'오늘의 작은 계획 고르기':'전체 할 일',picker?'지금 챙길 일 세 개만 골라보세요.':'필요할 때 하나씩 꺼내보세요.'],inbox:['생각을 내려놓는 수집함','지금 정리하지 않아도 괜찮아요.'],waiting:['잠시 멈춰둔 일','준비가 되면, 여기서 이어가세요.'],done:['차곡차곡, 해낸 일','작은 걸음들이 모여 있어요.']};$('#heading').textContent=titles[view][0];$('#subtitle').textContent=titles[view][1];
const a=active();if(a){$('#focus-content').innerHTML=`<h2 class="focus-task-title">${esc(a.title)}</h2><div class="focus-next">${esc(a.next||a.note||'지금은 이 한 가지만 생각해요.')}</div><div class="focus-actions"><button class="primary" data-action="done" data-id="${esc(a.id)}">✓ 완료했어요</button><button class="secondary" data-action="pause" data-id="${esc(a.id)}">잠시 보류</button><button class="text-button" data-action="edit" data-id="${esc(a.id)}">메모 · 작은 단계</button>${state.settings.timer?'<div class="timer"><output id="timer-output">05:00</output><select id="timer-minutes" aria-label="집중 시간"><option value="5">5분</option><option value="10">10분</option><option value="25">25분</option></select><button id="timer-toggle">타이머 시작</button></div>':''}</div>`;if($('#timer-toggle')){$('#timer-toggle').onclick=()=>{if(timer.end){timer.left=Math.max(0,Math.ceil((timer.end-Date.now())/1000));timer.end=0}else{timer.task=a.id;timer.end=Date.now()+timer.left*1000}tick()};$('#timer-minutes').onchange=e=>{timer.left=Number(e.target.value)*60;timer.end=0;tick()};tick()}}else{const last=state.tasks.filter(t=>t.status==='paused').sort((x,y)=>y.updated-x.updated)[0];$('#focus-content').innerHTML=`<div class="focus-empty"><h2>${last?'하던 일, 이어서 해볼까요?':'지금은 무엇부터 해볼까요?'}</h2><p>${esc(last?last.title:'할 일 하나를 고르면, 여기에 담아둘게요.')}</p><button class="primary" ${last?`data-action="start" data-id="${esc(last.id)}"`:'id="pick-first"'}>${last?'이어서 하기 →':'첫 한 걸음 고르기 →'}</button></div>`;if($('#pick-first'))$('#pick-first').onclick=()=>navigate('all')}
const planned=state.tasks.filter(t=>t.today&&t.status!=='done');$('#today-count').textContent=`${planned.length} / 3`;$('#today-list').innerHTML=planned.map(row).join('')||'<div class="empty-state"><span>＋</span>아직 정하지 않아도 괜찮아요.<br>떠오른 일을 적고, 오늘 할 일에 담아보세요.</div>';const completed=state.tasks.filter(t=>t.completed===today).length;$('#progress-label').textContent=completed?`오늘 ${completed}개의 한 걸음을 마쳤어요`:'작은 시작도 한 걸음이에요';$('#progress-bar').style.width=`${completed?completed/(completed+planned.length)*100:0}%`;renderList()}
function renderList(){let list=state.tasks.filter(t=>view==='done'?t.status==='done':view==='waiting'?['paused','waiting'].includes(t.status):view==='inbox'?t.status==='todo'&&!t.today&&!t.start&&!t.due:t.status!=='done');const query=$('#search').value.toLocaleLowerCase();list=list.filter(t=>`${t.title} ${t.note}`.toLocaleLowerCase().includes(query));const filter=$('#filter').value,today=dateKey();list=list.filter(t=>filter==='today'?t.today||t.start===today||t.due===today:filter==='future'?t.start>today||t.due>today:filter==='overdue'?t.due&&t.due<today:filter==='undated'?!t.start&&!t.due:true);const sort=$('#sort').value;list.sort((a,b)=>sort==='due'?(a.due||'9999').localeCompare(b.due||'9999'):sort==='priority'?b.priority-a.priority:b.created-a.created);$('#task-list').innerHTML=list.map(row).join('')||'<div class="empty-state"><span>✧</span>여기는 비어 있어요.<br>필요한 일이 생기면 가볍게 적어두세요.</div>'}
function navigate(v,choose=false){view=v;picker=choose;$('#search').value='';$('#filter').value='any';render()}
function openTask(t){selected=t.id;const map={title:'title',next:'next',note:'note',start:'start',due:'due',priority:'priority',status:'status',estimate:'estimate',tag:'tag',repeat:'repeat',reminder:'reminder',condition:'condition'};for(const[id,key]of Object.entries(map))$(`#edit-${id}`).value=t[key]??'';$('#detail-done').textContent=t.status==='done'?'완료 취소':'완료';$('#detail-today').textContent=t.today?'오늘에서 빼기':'오늘에 담기';renderSteps(t);if(!$('#task-dialog').open)$('#task-dialog').showModal()}
function renderSteps(t){$('#steps').innerHTML=t.steps.map(s=>`<div class="step-row ${s.done?'finished':''}"><input type="checkbox" ${s.done?'checked':''} data-step="${esc(s.id)}" aria-label="${esc(s.title)}"><span>${esc(s.title)}</span><button data-remove-step="${esc(s.id)}" aria-label="단계 삭제">×</button></div>`).join('')}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b){const t=state.tasks.find(t=>t.id===b.dataset.id);if(!t)return;const a=b.dataset.action;if(a==='start')start(t);if(a==='done')complete(t);if(a==='today')toggleToday(t);if(a==='edit')openTask(t);if(a==='pause'){t.status='paused';update(t);render();openTask(t);$('#edit-note').focus()}}const n=e.target.closest('[data-view]');if(n)navigate(n.dataset.view);const c=e.target.closest('[data-close]');if(c)$(`#${c.dataset.close}`).close();const remove=e.target.closest('[data-remove-step]');if(remove){const t=state.tasks.find(t=>t.id===selected);t.steps=t.steps.filter(s=>s.id!==remove.dataset.removeStep);update(t);renderSteps(t)}});
$('#quick-input').addEventListener('input',e=>{try{localStorage.setItem(DRAFT,e.target.value)}catch{}});$('#quick-add').onsubmit=e=>{e.preventDefault();const title=$('#quick-input').value.trim();if(!title){$('#quick-input').focus();return}state.tasks.push(newTask(title));save();$('#quick-input').value='';try{localStorage.removeItem(DRAFT)}catch{}render();toast('적어두었어요. 필요할 때 꺼내보세요.');$('#quick-input').focus()};$('#choose-today').onclick=()=>navigate('all',true);$('#search').oninput=renderList;$('#filter').onchange=renderList;$('#sort').onchange=renderList;
for(const field of ['title','next','note','start','due','priority','status','estimate','tag','repeat','reminder','condition'])$(`#edit-${field}`).addEventListener('input',e=>{const t=state.tasks.find(t=>t.id===selected);if(!t)return;if(field==='title'&&!e.target.value.trim()){$('#save-label').textContent='제목을 입력해 주세요';return}if(field==='status'&&e.target.value==='done'&&t.status!=='done'){complete(t);openTask(t);return}if(field==='status'&&e.target.value==='active'){start(t);return}t[field]=['priority','estimate'].includes(field)?Number(e.target.value):e.target.value;if(field==='reminder')t.notified='';if(field==='status'&&t.status!=='done')t.completed='';update(t);$('#save-label').textContent='저장했어요';render()});
$('#task-dialog').addEventListener('close',()=>render());$('#steps').onchange=e=>{if(!e.target.dataset.step)return;const t=state.tasks.find(t=>t.id===selected),s=t.steps.find(s=>s.id===e.target.dataset.step);s.done=e.target.checked;update(t);renderSteps(t)};$('#step-form').onsubmit=e=>{e.preventDefault();const title=$('#step-input').value.trim();if(!title)return;const t=state.tasks.find(t=>t.id===selected);t.steps.push({id:uid(),title,done:false});update(t);$('#step-input').value='';renderSteps(t)};
$('#detail-start').onclick=()=>{const t=state.tasks.find(t=>t.id===selected);start(t);$('#task-dialog').close();navigate('home')};$('#detail-done').onclick=()=>{const t=state.tasks.find(t=>t.id===selected);complete(t);$('#task-dialog').close()};$('#detail-today').onclick=()=>{const t=state.tasks.find(t=>t.id===selected);toggleToday(t);$('#detail-today').textContent=t.today?'오늘에서 빼기':'오늘에 담기'};$('#delete-task').onclick=()=>{const t=state.tasks.find(t=>t.id===selected),index=state.tasks.indexOf(t);state.tasks.splice(index,1);save();$('#task-dialog').close();render();toast('할 일을 삭제했어요.',()=>{state.tasks.splice(index,0,t);save();render()})};
$('#settings-btn').onclick=()=>{$('#setting-timer').checked=state.settings.timer;$('#setting-notify').checked=state.settings.notify;$('#settings-dialog').showModal()};$('#setting-timer').onchange=e=>{state.settings.timer=e.target.checked;save();render()};$('#setting-notify').onchange=async e=>{if(e.target.checked){if(!('Notification'in window)){e.target.checked=false;toast('이 환경에서는 브라우저 알림을 지원하지 않아요.');return}let permission=Notification.permission;if(permission==='default')permission=await Notification.requestPermission();if(permission!=='granted'){e.target.checked=false;toast('브라우저 설정에서 알림을 허용해 주세요.');return}}state.settings.notify=e.target.checked;save()};
$('#export').onclick=()=>{const blob=new Blob([JSON.stringify({version:1,...state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`한걸음-백업-${dateKey()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)};$('#import-btn').onclick=()=>$('#import-file').click();
function validTask(t){return t&&typeof t.id==='string'&&t.id.length<150&&typeof t.title==='string'&&t.title.trim()&&t.title.length<=200&&['todo','active','paused','waiting','done'].includes(t.status)&&Array.isArray(t.steps)&&t.steps.every(s=>s&&typeof s.id==='string'&&typeof s.title==='string'&&typeof s.done==='boolean')&&['note','next','start','due','tag','condition','reminder','repeat','completed'].every(k=>t[k]===undefined||typeof t[k]==='string')&&Number.isFinite(t.created)&&Number.isFinite(t.priority)}
$('#import-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5e6)throw Error();const data=JSON.parse(await file.text());if(!Array.isArray(data.tasks)||data.tasks.length>10000||!data.tasks.every(validTask))throw Error();let count=0;for(const raw of data.tasks){if(state.tasks.some(t=>t.id===raw.id))continue;const t={...newTask(raw.title),...raw};if(t.status==='active'&&active())t.status='paused';state.tasks.push(t);count++}save();render();toast(`${count}개의 할 일을 가져왔어요.`)}catch{toast('올바른 한걸음 백업 파일을 선택해 주세요.')}e.target.value=''};
function checkLegacyImport(){let hasLegacy=false;try{const raw=JSON.parse(localStorage.getItem('one-step-v1'));hasLegacy=Array.isArray(raw?.tasks)&&raw.tasks.length>0}catch{}$('#import-legacy').hidden=!hasLegacy;$('#legacy-note').hidden=!hasLegacy}
$('#import-legacy').onclick=()=>{try{const legacy=JSON.parse(localStorage.getItem('one-step-v1'));if(!Array.isArray(legacy?.tasks)||legacy.tasks.length>10000||!legacy.tasks.every(validTask))throw Error('Invalid legacy data');let count=0;for(const raw of legacy.tasks){if(state.tasks.some(t=>t.id===raw.id))continue;const task={...newTask(raw.title),...raw};if(task.status==='active'&&active())task.status='paused';state.tasks.push(task);count++}save();render();toast(count+'개의 이전 기록을 가져왔어요. 기존 브라우저 기록은 그대로 남아 있어요.')}catch{toast('이전 기록을 가져오지 못했어요. 백업 파일을 이용해 주세요.')}};
checkLegacyImport();
function tick(){const output=$('#timer-output');if(!output)return;let left=timer.end?Math.max(0,Math.ceil((timer.end-Date.now())/1000)):timer.left;output.textContent=`${String(Math.floor(left/60)).padStart(2,'0')}:${String(left%60).padStart(2,'0')}`;$('#timer-toggle').textContent=timer.end?'잠시 멈춤':left===0?'다시 시작':'타이머 시작';if(timer.end&&left===0){timer.end=0;timer.left=300;toast('잠깐 숨을 돌려요. 계속하거나 쉬어도 괜찮아요.')}}
setInterval(()=>{tick();if(state.settings.notify&&'Notification'in window&&Notification.permission==='granted'){const now=Date.now();for(const t of state.tasks){const time=new Date(t.reminder).getTime();if(t.status!=='done'&&time&&time<=now&&t.notified!==t.reminder){const n=new Notification('한걸음 · 가볍게 확인해요',{body:t.title,tag:t.id});n.onclick=()=>{window.focus();openTask(t);n.close()};t.notified=t.reminder;save()}}}if($('#date-label').dataset.day!==dateKey()){$('#date-label').dataset.day=dateKey();render()}},1000);
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(!document.querySelector('dialog[open]'))$('#quick-input').focus()}});render();if(!storageOK)toast('브라우저 저장소를 확인해 주세요. 백업 기능을 사용할 수 있어요.');

